class FailoverType(Boto3Model):
    """
    Specifies failover configuration for multi-region user pool domains.

    Contains settings for the secondary region and health check configuration.
    """

    SecondaryRegion: str
    """
    The secondary Amazon Web Services Region to use for failover when the primary region
    becomes unavailable.
    """

    PrimaryRoute53HealthCheckId: str
    """
    The ID of the Amazon Web Services Route53 healthcheck that controls routing.

    If the healthcheck is healthy, traffic will be routed to the primary replica, and if
    the healthcheck is unhealthy, traffic will be routed to the secondary region.
    """

class RoutingType(Boto3Model):
    """
    Specifies routing configuration for user pool domains.

    Contains failover settings for multi-region deployments.
    """

    Failover: "FailoverType | None" = None
    """
    The failover configuration that specifies the secondary region and health check
    settings.
    """

class CognitoUserPoolDomain(PrimaryBoto3Model):
    """
    A container for information about the user pool domain associated with the hosted UI
    and OAuth endpoints.
    """

    manager_class: ClassVar[ModelType[Boto3ModelManager]] = CognitoUserPoolDomainManager

    UserPoolId: "str | None" = None
    """
    The ID of the user pool that the domain is attached to.
    """

    AWSAccountId: str = Field(default=None, frozen=True)
    """
    The Amazon Web Services account that you created the user pool in.
    """

    Domain: "str | None" = None
    """
    The domain string.

    For custom domains, this is the fully-qualified domain name, such as
    ``auth.example.com``. For Amazon Cognito prefix domains, this is the prefix alone,
    such as ``auth``.
    """

    S3Bucket: str = Field(default=None, frozen=True)
    """
    The Amazon S3 bucket where the static files for this domain are stored.
    """

    CloudFrontDistribution: str = Field(default=None, frozen=True)
    """
    The Amazon CloudFront endpoint that hosts your custom domain.
    """

    Version: str = Field(default=None, frozen=True)
    """
    The app version.
    """

    Status: Literal["CREATING", "DELETING", "UPDATING", "ACTIVE", "FAILED"] = Field(
        default=None, frozen=True
    )
    """
    The domain status.
    """

    CustomDomainConfig: "CustomDomainConfigType | None" = None
    """
    The configuration for a custom domain that hosts the sign-up and sign-in webpages
    for your application.
    """

    ManagedLoginVersion: "int | None" = None
    """
    The version of managed login branding that you want to apply to your domain.

    A value of ``1`` indicates hosted UI (classic) branding and a version of ``2``
    indicates managed login branding.
    """

    Routing: "RoutingType | None" = None
    """
    The routing configuration for the domain, including failover settings for multi-
    region deployments.

    Currently only
    ``Failover`` configurations are allowed.
    """
    @property
    def pk(self) -> str | None:
        """
        Return the primary key of the model.

        This is the value of the :py:attr:`Domain` attribute.

        Returns:
            The primary key of the model instance.
        """
        return self.Domain

    def __hash__(self) -> int:
        """
        Return the hash of the model.

        This is the value of the
        :py:attr:`Domain` attribute.
        """
        return hash(self.Domain)

